/** The panel's injected stylesheet text. */
export declare const cssText = "\n.dsh_filePanel_trigger {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 28px;\n  height: 28px;\n  border: 0;\n  border-radius: 14px;\n  background: none;\n  color: var(--dsw-alias-label-dimmed);\n  cursor: pointer;\n}\n.dsh_filePanel_trigger:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_filePanel_trigger svg {\n  width: 15px;\n  height: 15px;\n}\n.dsh_filePanel_popover {\n  display: flex;\n  flex-direction: column;\n  gap: 0;\n  width: 440px;\n  max-width: calc(100vw - 32px);\n  max-height: min(520px, calc(100vh - 120px));\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 12px;\n  background: var(--dsw-alias-bg-layer-1);\n  box-shadow: var(--dsw-shadow-popover, 0 8px 24px rgb(0 0 0 / 0.12));\n  overflow: hidden;\n}\n.dsh_filePanel_header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 12px;\n  border-bottom: 1px solid var(--dsw-alias-border-l1);\n}\n.dsh_filePanel_title {\n  flex: 1;\n  min-width: 0;\n  margin: 0;\n  color: var(--dsw-alias-label-primary);\n  font-size: 14px;\n  line-height: 20px;\n  font-weight: 600;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.dsh_filePanel_iconButton {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  flex: none;\n  width: 26px;\n  height: 26px;\n  border: 0;\n  border-radius: 13px;\n  background: none;\n  color: var(--dsw-alias-label-dimmed);\n  cursor: pointer;\n}\n.dsh_filePanel_iconButton:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_filePanel_iconButton svg {\n  width: 14px;\n  height: 14px;\n}\n.dsh_filePanel_crumbs {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  padding: 6px 12px;\n  border-bottom: 1px solid var(--dsw-alias-border-l1);\n  overflow-x: auto;\n  scrollbar-width: thin;\n}\n.dsh_filePanel_crumb {\n  display: inline-flex;\n  align-items: center;\n  flex: none;\n  padding: 2px 6px;\n  border: 0;\n  border-radius: 8px;\n  background: none;\n  color: var(--dsw-alias-label-tertiary);\n  font: inherit;\n  font-size: 12px;\n  line-height: 18px;\n  cursor: pointer;\n}\n.dsh_filePanel_crumb:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_filePanel_crumbSep {\n  flex: none;\n  color: var(--dsw-alias-label-dimmed);\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh_filePanel_body {\n  flex: 1;\n  min-height: 120px;\n  max-height: 400px;\n  overflow-y: auto;\n  padding: 4px;\n}\n.dsh_filePanel_row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  padding: 5px 8px;\n  border: 0;\n  border-radius: 8px;\n  background: none;\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  line-height: 20px;\n  text-align: left;\n  cursor: pointer;\n}\n.dsh_filePanel_row:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n.dsh_filePanel_rowIcon {\n  flex: none;\n  width: 15px;\n  height: 15px;\n  color: var(--dsw-alias-label-dimmed);\n}\n.dsh_filePanel_rowName {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.dsh_filePanel_rowMeta {\n  flex: none;\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh_filePanel_note {\n  padding: 14px 12px;\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 13px;\n  line-height: 20px;\n  text-align: center;\n}\n.dsh_filePanel_error {\n  padding: 14px 12px;\n  color: var(--dsw-alias-danger-text, var(--dsw-alias-label-primary));\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_filePanel_editor {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 12px;\n}\n.dsh_filePanel_field {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.dsh_filePanel_label {\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh_filePanel_input,\n.dsh_filePanel_textarea {\n  width: 100%;\n  box-sizing: border-box;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  background: var(--dsw-alias-bg-layer-2);\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  line-height: 20px;\n}\n.dsh_filePanel_input {\n  padding: 5px 8px;\n}\n.dsh_filePanel_textarea {\n  min-height: 220px;\n  padding: 8px;\n  resize: vertical;\n  font-family: var(--dsw-font-mono, ui-monospace, monospace);\n  tab-size: 2;\n}\n.dsh_filePanel_actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n}\n.dsh_filePanel_button {\n  padding: 4px 14px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  background: var(--dsw-alias-bg-layer-2);\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  line-height: 20px;\n  cursor: pointer;\n}\n.dsh_filePanel_button:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n.dsh_filePanel_buttonPrimary {\n  border-color: transparent;\n  background: var(--dsw-alias-brand-primary);\n  color: var(--dsw-alias-label-inverse, #fff);\n}\n.dsh_filePanel_buttonPrimary:hover {\n  background: var(--dsw-alias-brand-primary-hover, var(--dsw-alias-brand-primary));\n}\n.dsh_filePanel_button:disabled {\n  opacity: 0.55;\n  cursor: default;\n}\n.dsh_filePanel_readContent {\n  padding: 12px;\n  margin: 0;\n  color: var(--dsw-alias-label-primary);\n  font-family: var(--dsw-font-mono, ui-monospace, monospace);\n  font-size: 12px;\n  line-height: 19px;\n  white-space: pre-wrap;\n  word-break: break-word;\n  overflow-wrap: anywhere;\n}\n";
